const SPRITES={}; // Text-only guide; artwork library removed.
function monRowHTML(m){
  const rankBadge = m.rk ? `<span class="rank rk-${m.rk}">${m.rk}</span>` : '';
  const detail = (m.role || m.mv) ? `<div class="mondetail">${m.role?`<b>${m.role}</b>`:''}${(m.role && m.mv) ? ' · ' : ''}${m.mv?`ท่าแนะนำ: ${m.mv}`:''}</div>` : '';
  const sprite = SPRITES[m.n]
    ? `<img class="mon-icon" src="data:image/png;base64,${SPRITES[m.n]}" alt="${m.n}" width="24" height="24">`
    : `<span class="mon-icon mon-icon-placeholder">?</span>`;
  return `<div class="catchrow${m.s?' star':''}">${sprite}${rankBadge}${m.s?'★ ':''}<b>${m.n}</b> <span class="ty">${m.ty}</span> <span class="lv">Lv.${m.lv}</span> <span class="m">${m.m}</span>${detail}</div>`;
}
function catchBoxHTML(n){
  const locs = CATCHMAP[n];
  if(!locs || !locs.length) return '';
  const body = locs.map(L=>`<div class="catchloc"><div class="locname">▸ ${L.loc}</div>${L.mons.map(monRowHTML).join('')}</div>`).join('');
  const hasStar = locs.some(L=>L.mons.some(m=>m.s));
  return `<div class="catchbox"><div class="title">📍 จับได้ระหว่างทาง${hasStar?' — ★ = เตรียมสู้ยิมถัดไป · ตัวเลข = แรงค์':' · ตัวเลข = แรงค์'}</div>${body}</div>`;
}

