/* ---- gym badge tracker (แทนที่แถบปุ่มซ้ำซ้อนเดิม) ---- */
const BADGE_KEY = 'sg_badges_v1';
const GYM_STOPS = STORY.filter(s => s.gym && s.badge);

function loadBadgeProgress(){
  try{ return JSON.parse(localStorage.getItem(BADGE_KEY)) || {}; }catch(e){ return {}; }
}
function saveBadgeProgress(data){
  try{ localStorage.setItem(BADGE_KEY, JSON.stringify(data)); }catch(e){}
}

function renderBadgeRow(){
  const collected = loadBadgeProgress();
  const doneCount = GYM_STOPS.filter(s => collected[s.n]).length;
  document.getElementById('badgerow').innerHTML =
    `<span class="badgerow-label">🏅 ${doneCount}/${GYM_STOPS.length}</span>` +
    GYM_STOPS.map(s => `<span class="badgechip ${collected[s.n] ? 'done' : ''}" data-n="${s.n}" title="แตะเพื่อทำเครื่องหมายว่าเก็บแล้ว">${s.badge}</span>`).join('');

  document.querySelectorAll('#badgerow .badgechip').forEach(chip => {
    chip.addEventListener('click', () => {
      const n = chip.getAttribute('data-n');
      const data = loadBadgeProgress();
      data[n] = !data[n];
      saveBadgeProgress(data);
      renderBadgeRow();
    });
  });
}
renderBadgeRow();


function bossBox(b){
  if(!b) return '';
  const cls = b.type;
  return `<div class="gymbox">
    <span class="bosslabel ${cls}">${b.label}</span>
    <div class="mons">${b.mons}</div>
    <div class="tip"><b>วิธีรับมือ:</b> ${b.tip}</div>
  </div>`;
}

function renderStory(){
  let html = '<div class="trail">';
  STORY.forEach(s=>{
    html += `<div class="stop ${s.gym?'gym':''}" data-n="${s.n}">
      <div class="card">
        <h3>${s.title}</h3>
        ${s.lv?`<div class="lv">${s.lv}</div>`:''}
        ${catchBoxHTML(s.n)}
        <ul>${s.steps.map(x=>`<li>${x}</li>`).join('')}</ul>
        ${bossBox(s.boss)}
        ${s.steps2?`<ul>${s.steps2.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}
        ${bossBox(s.boss2)}
        ${s.steps3?`<ul>${s.steps3.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}
        ${bossBox(s.boss3)}
        ${s.steps4?`<ul>${s.steps4.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}
        ${bossBox(s.boss4)}
        ${bossBox(s.boss5)}
        ${s.next?`<p><b>ต่อไป:</b> ${s.next}</p>`:''}
      </div>
    </div>`;
  });
  html += '</div>';
  document.getElementById('pane-story').innerHTML = html;
}

