function renderPokedex() {
  let html = '';
  ['S', 'A', 'B', 'C', 'D'].forEach(rank => {
    html += `<div class="stitle"><span class="dot"></span>โปเกมอนระดับ ${rank}</div><div class="mon-grid">`;
    const monsInRank = Object.entries(POKEMON_DEEP_STATS).map(([name,p])=>({name, ...p})).filter(p => p.rank === rank).sort((a,b)=>a.no - b.no);
    monsInRank.forEach(p => {
      const sprite = SPRITES[p.name] ? `<img src="data:image/png;base64,${SPRITES[p.name]}">` : '<div class="mon-icon-placeholder" style="width:44px;height:44px;border-radius:8px;">?</div>';
      html += `<div class="mon-grid-chip" onclick="openMonOverlay('${p.name}')">
        ${sprite}
        <div class="name">${p.name}</div>
      </div>`;
    });
    html += `</div>`;
  });
  document.getElementById('pane-pokedex').innerHTML = html;
}

function openMonOverlay(name) {
  const ds = POKEMON_DEEP_STATS[name];
  if(!ds) return;
  
  let entries = [];
  Object.values(CATCHMAP).forEach(locs => {
    locs.forEach(L => {
      L.mons.forEach(m => {
        if(m.n === name) entries.push({loc: L.loc, ty: m.ty, lv: m.lv, m: m.m});
      });
    });
  });
  // Deduplicate entries if any
  const uniqueEntries = Array.from(new Set(entries.map(e=>e.loc))).map(loc => {
    return entries.find(e=>e.loc === loc);
  });
  if(uniqueEntries.length === 0) {
    if(OBTAIN_INFO[name]) {
      OBTAIN_INFO[name].forEach(e => uniqueEntries.push({loc: e.loc, m: e.m, ty: e.ty || '', lv: e.lv || ''}));
    } else {
      {const _ch=EVO_CHAINS[name]||[],_ix=_ch.indexOf(name);if(_ix>0){uniqueEntries.push({loc:'ได้จากการวิวัฒนาการจาก '+_ch[_ix-1],m:'Evolution',ty:'',lv:''});}else{uniqueEntries.push({loc:'ยังไม่มีข้อมูลจุดได้รับ (ตัวตั้งต้น / ของขวัญ / ตำนาน / ไข่)',m:'Special',ty:'',lv:''});}}
    }
  }

  const dummyMon = { name: name, entries: uniqueEntries };
  const cardHtml = buildDeepStatsCard(dummyMon, ds);
  
  const overlay = document.getElementById('monOverlay');
  overlay.innerHTML = cardHtml;
  overlay.querySelector('.dc-close').onclick = () => overlay.classList.remove('show');
  overlay.classList.add('show');
}

renderPokedex();


