/* ---------------- search ---------------- */
function filterContent(q){
  q = q.trim().toLowerCase();
  const activePane = document.querySelector('.tab.active').dataset.tab;
  const container = document.getElementById('pane-'+activePane);
  const cards = container.querySelectorAll('.card, .acc, .ballcard');
  cards.forEach(c=>{
    if(!q){ c.style.display=''; return; }
    const txt = c.textContent.toLowerCase();
    c.style.display = txt.includes(q) ? '' : 'none';
  });
}
document.getElementById('search').addEventListener('input', e=> filterContent(e.target.value));



/* ---------------- journey: build flattened step list ---------------- */
const JOURNEY_KEY = 'sg_journey_v1';

function buildJourneyItems(startIdx){
  const items = [];
  for(let i=startIdx; i<STORY.length; i++){
    const s = STORY[i];
    const pushSteps = (arr)=>{ if(arr) arr.forEach(t=> items.push({nodeIdx:i, kind:'step', text:t})); };
    if(CATCHMAP[s.n] && CATCHMAP[s.n].length) items.push({nodeIdx:i, kind:'catch'});
    if(s.guide){
      const guides = Array.isArray(s.guide) ? s.guide : [s.guide];
      guides.forEach(g=> items.push({nodeIdx:i, kind:'guide', guide:g}));
    }
    pushSteps(s.steps);
    if(s.boss) items.push({nodeIdx:i, kind:'boss', boss:s.boss});
    pushSteps(s.steps2);
    if(s.boss2) items.push({nodeIdx:i, kind:'boss', boss:s.boss2});
    pushSteps(s.steps3);
    if(s.boss3) items.push({nodeIdx:i, kind:'boss', boss:s.boss3});
    pushSteps(s.steps4);
    if(s.boss4) items.push({nodeIdx:i, kind:'boss', boss:s.boss4});
    if(s.boss5) items.push({nodeIdx:i, kind:'boss', boss:s.boss5});
    if(s.next) items.push({nodeIdx:i, kind:'transition', text:s.next});
  }
  return items;
}

function saveJourneyProgress(startIdx, pos){
  try{ localStorage.setItem(JOURNEY_KEY, JSON.stringify({startIdx, pos})); }catch(e){}
}
function loadJourneyProgress(){
  try{ const raw = localStorage.getItem(JOURNEY_KEY); return raw ? JSON.parse(raw) : null; }catch(e){ return null; }
}
function clearJourneyProgress(){ try{ localStorage.removeItem(JOURNEY_KEY); }catch(e){} }

let journeyItems = [];
let journeyStartIdx = 0;
let journeyPos = 0;

/* ---------------- bottom sheet: "which city am I in" ---------------- */
const whereOptions = STORY.map((s,i)=>({v:i, label:`${s.n}. ${s.title}`}));
const sel = document.getElementById('whereSelect');
sel.innerHTML = '<option value="">— เลือกจุดที่อยู่ตอนนี้ —</option>' + whereOptions.map(o=>`<option value="${o.v}">${o.label}</option>`).join('');

const sheet = document.getElementById('sheet');
const backdrop = document.getElementById('backdrop');
const startBtn = document.getElementById('startJourneyBtn');
const resumeSlot = document.getElementById('resumeSlot');

function renderResumeSlot(){
  const prog = loadJourneyProgress();
  if(!prog){ resumeSlot.innerHTML = ''; return; }
  const items = buildJourneyItems(prog.startIdx);
  const item = items[Math.min(prog.pos, items.length-1)];
  if(!item){ resumeSlot.innerHTML = ''; return; }
  const node = STORY[item.nodeIdx];
  resumeSlot.innerHTML = `<div class="resumebar">
    ค้างอยู่ที่ <b>${node.title}</b>
    <div class="row">
      <button id="resumeContinue">ทำต่อจากเดิม</button>
      <button class="primary" id="resumeNew">เริ่มใหม่จากจุดอื่น</button>
    </div>
  </div>`;
  document.getElementById('resumeContinue').addEventListener('click', ()=>{
    openJourney(prog.startIdx, prog.pos);
    closeSheet();
  });
  document.getElementById('resumeNew').addEventListener('click', ()=>{
    clearJourneyProgress();
    renderResumeSlot();
  });
}

function openSheet(){
  sheet.classList.add('show'); backdrop.classList.add('show');
  renderResumeSlot();
}
function closeSheet(){ sheet.classList.remove('show'); backdrop.classList.remove('show'); }
document.getElementById('whereBtn').addEventListener('click', openSheet);
backdrop.addEventListener('click', closeSheet);

sel.addEventListener('change', ()=>{
  const v = sel.value;
  const ans = document.getElementById('whereAnswer');
  if(v===''){ ans.style.display='none'; startBtn.classList.add('hidden'); return; }
  const s = STORY[parseInt(v)];
  ans.style.display='block';
  ans.innerHTML = `<b>${s.title}</b><div style="margin-top:6px;">${s.steps[0]}</div>`;
  startBtn.classList.remove('hidden');
  startBtn.dataset.idx = v;
});

startBtn.addEventListener('click', ()=>{
  const idx = parseInt(startBtn.dataset.idx);
  openJourney(idx, 0);
  closeSheet();
});



function buildDeepStatsCard(mon, ds) {
  const sprite = SPRITES[mon.name] ? `data:image/png;base64,${SPRITES[mon.name]}` : '';
  const isMega = ds.mega === 'Yes';
  
  // Parse types
  const types = ds.type.match(/[ก-๙a-zA-Z]+/g) || [ds.type];
  const typeHtml = types.map(t => `<span>${t}</span>`).join('');
  
  const rankDesc = ds.rank === 'S' ? 'ระดับตำนาน/สุดยอด — ตัวแบกทีมจนจบเกม' : ds.rank === 'A' ? 'ระดับแกร่งมาก — ตัวหลักที่พึ่งพาได้ตลอด' : 'ระดับดี — คุ้มค่าแก่การปั้นใช้งาน';
  const roleDesc = ds.role || `บทบาท: ไม่ระบุ · BST รวม <b>${ds.bst || '?'}</b>`;
  
  const makeBar = (label, val) => {
    const num = parseInt(val) || 0;
    const pct = Math.min((num / 200) * 100, 100);
    const color = num >= 110 ? '#6bd3a0' : '#e8b64c';
    return `<div class="dc-stat-row">
      <div class="dc-stat-label">${label}</div>
      <div class="dc-stat-bar-bg"><div class="dc-stat-bar-fill" style="width:${pct}%; background-color:${color}"></div></div>
      <div class="dc-stat-val">${num}</div>
    </div>`;
  };
  
  const ab = ds.ab ? ds.ab.split('/').map(s => `<span class="dc-ab-tag">${s.trim()}</span>`).join('') : '';
  const ha = ds.ha ? `<span class="dc-ab-tag ha">${ds.ha}</span>` : '';
  const innate = ds.innate ? ds.innate.split(',').map(s => `<span class="dc-ab-tag in">${s.trim()}</span>`).join('') : '';
  
  const moves = ds.moves.map(m => `<div class="dc-move">${m}</div>`).join('');

  // Evolution chain (if this species belongs to one)
  const chain = (typeof EVO_CHAINS !== 'undefined') ? EVO_CHAINS[mon.name] : null;
  let evoHtml = '';
  if (chain && chain.length > 1) {
    evoHtml = `
      <div class="dc-location-title">🧬 สายวิวัฒนาการ</div>
      <div class="dc-evo-chain" style="display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:6px 0 10px;">
        ${chain.map((stageName, i) => {
          const isCurrent = stageName === mon.name;
          const stageSprite = SPRITES[stageName] ? `<img src="data:image/png;base64,${SPRITES[stageName]}" style="width:32px;height:32px;vertical-align:middle;">` : '';
          const chip = `<span class="dc-ab-tag${isCurrent ? ' ha' : ''}" style="cursor:${POKEMON_DEEP_STATS[stageName] ? 'pointer' : 'default'};" ${POKEMON_DEEP_STATS[stageName] ? `onclick=\"openMonOverlay('${stageName.replace(/'/g,"\\'")}')\"` : ''}>${stageSprite} ${stageName}</span>`;
          return i < chain.length - 1 ? chip + '<span style="opacity:0.5;">→</span>' : chip;
        }).join('')}
      </div>`;
  }

  // Combine locations from original encounter mapping
  const locsHtml = mon.entries.map(en=>
    `<div>▸ ${en.loc} <span style="opacity:0.6;font-size:11px;">(${en.m})</span></div>`
  ).join('');

  return `
    <div class="deep-card">
      <div class="dc-header">
        ${sprite ? `<img src="${sprite}" class="dc-icon">` : ''}
        <div class="dc-title">
          <div class="dc-no">#${ds.no}</div>
          <h3 class="dc-name">${mon.name}</h3>
          <div class="dc-types">${typeHtml}</div>
        </div>
        <button class="dc-close" onclick="this.closest('.tr-detail').classList.add('hidden')">✕</button>
      </div>
      
      ${isMega ? `<div class="dc-mega">✦ <b>มีร่าง Mega</b></div>` : ''}
      
      <div class="dc-rankbox">
        <span class="rank rk-${ds.rank}">${ds.rank}</span> ${rankDesc}
      </div>
      
      <div class="dc-role">${roleDesc}</div>
      
      <div class="dc-stats">
        ${makeBar('HP', ds.hp)}
        ${makeBar('โจมตี', ds.atk)}
        ${makeBar('ป้องกัน', ds.def)}
        ${makeBar('พลังพิเศษ', ds.spa)}
        ${makeBar('กันพิเศษ', ds.spd)}
        ${makeBar('ความเร็ว', ds.spe)}
      </div>
      
      <div class="dc-abilities">
        ${ab ? `<div class="dc-ab-row"><div class="dc-ab-label">ความสามารถ</div><div class="dc-ab-val">${ab}</div></div>` : ''}
        ${ha ? `<div class="dc-ab-row"><div class="dc-ab-label" style="color:var(--ok);">ซ่อน (HA)</div><div class="dc-ab-val">${ha}</div></div>` : ''}
        ${innate ? `<div class="dc-ab-row"><div class="dc-ab-label" style="color:var(--danger);">Innate</div><div class="dc-ab-val">${innate}</div></div>` : ''}
      </div>
      
      ${evoHtml}

      <div class="dc-moves-title">ชุดท่าแนะนำ 4 ท่า <span class="dc-moves-desc">[ดึงข้อมูลจากท่าที่เรียนรู้ได้ตามเลเวล]</span></div>
      ${moves}
      
      <div class="dc-location-title">📍 พบได้ที่</div>
      <div class="dc-location-body">${locsHtml}</div>
    </div>
  `;
}

/* ---------------- journey: full-screen step-through mode ---------------- */
const journeyEl = document.getElementById('journey');
const journeyCard = document.getElementById('journeyCard');
const journeyLoc = document.getElementById('journeyLoc');
const journeyFill = document.getElementById('journeyFill');
const journeyCount = document.getElementById('journeyCount');
const journeyNext = document.getElementById('journeyNext');
const journeyBack = document.getElementById('journeyBack');
const journeyTopRank = document.getElementById('journeyTopRank');

/* rank order best→worst, ใช้หาแรงค์สูงสุดของเมือง/จุดนั้นๆ */
const RANK_ORDER = ['S','A','B','C','D'];
function getRelevantMons(n){
  const locs = CATCHMAP[n];
  if(!locs || !locs.length) return null;
  const byName = new Map();
  let bestIdx = null;
  locs.forEach(L=> L.mons.forEach(m=>{
    if(!byName.has(m.n)) byName.set(m.n, { name:m.n, rk:m.rk||'', star:false, entries:[] });
    const rec = byName.get(m.n);
    if(m.s) rec.star = true;
    if(m.rk){
      const idx = RANK_ORDER.indexOf(m.rk);
      if(idx !== -1){
        if(!rec.rk || RANK_ORDER.indexOf(rec.rk) > idx) rec.rk = m.rk;
        if(bestIdx === null || idx < bestIdx) bestIdx = idx;
      }
    }
    rec.entries.push({loc:L.loc, ty:m.ty, lv:m.lv, m:m.m});
  }));
  const mons = [...byName.values()];
  if(mons.length === 0) return null;
  const bestRank = bestIdx !== null ? RANK_ORDER[bestIdx] : null;
  return { bestRank, mons };
}

let currentTopRankData = null;
function renderTopRank(n){
  const data = getRelevantMons(n);
  currentTopRankData = data;
  if(!data){ journeyTopRank.classList.add('hidden'); journeyTopRank.innerHTML=''; return; }
  journeyTopRank.classList.remove('hidden');

  const chipHTML = mn=>{
    const sprite = SPRITES[mn.name]
      ? `<img src="data:image/png;base64,${SPRITES[mn.name]}" alt="${mn.name}">`
      : '';
    const mark = mn.star ? '★ ' : '';
    return `<button type="button" class="tr-chip${mn.star?' tr-chip-star':''}" data-name="${mn.name}">${sprite}<span>${mark}${mn.name}</span></button>`;
  };

  const topRankMons = data.bestRank ? data.mons.filter(m=>m.rk===data.bestRank) : [];
  const starMons = data.mons.filter(m=>m.star);

  let html = '';
  if(topRankMons.length){
    html += `<div class="tr-label">แรงค์สูงสุดในจุดนี้ <span class="rank rk-${data.bestRank}">${data.bestRank}</span> · แตะตัวเพื่อดูรายละเอียด</div>
      <div class="tr-chips">${topRankMons.map(chipHTML).join('')}</div>`;
  }
  if(starMons.length){
    html += `<div class="tr-label" style="margin-top:${topRankMons.length ? '10px' : '0'};">★ แนะนำจับไว้สู้ยิมถัดไป</div>
      <div class="tr-chips">${starMons.map(chipHTML).join('')}</div>`;
  }
  journeyTopRank.innerHTML = html + `<div class="tr-detail hidden" id="journeyTopRankDetail"></div>`;
}

journeyTopRank.addEventListener('click', (e)=>{
  const chip = e.target.closest('.tr-chip');
  if(!chip || !currentTopRankData) return;
  const name = chip.dataset.name;
  const wasActive = chip.classList.contains('active');
  journeyTopRank.querySelectorAll('.tr-chip').forEach(c=>c.classList.remove('active'));
  const detailEl = journeyTopRank.querySelector('.tr-detail');
  if(wasActive){
    detailEl.classList.add('hidden');
    detailEl.innerHTML = '';
    return;
  }
  chip.classList.add('active');
  const mon = currentTopRankData.mons.find(mn=>mn.name===name);
  if(!mon){ detailEl.classList.add('hidden'); return; }
  
  // CHECK FOR DEEP STATS
  if(typeof POKEMON_DEEP_STATS !== 'undefined' && POKEMON_DEEP_STATS[name]){
    // Apply styling fixes to wrapper if needed
    detailEl.style.padding = '0';
    detailEl.style.background = 'transparent';
    detailEl.style.border = 'none';
    detailEl.innerHTML = buildDeepStatsCard(mon, POKEMON_DEEP_STATS[name]);
  } else {
    // FALLBACK
    detailEl.style.padding = '';
    detailEl.style.background = '';
    detailEl.style.border = '';
    detailEl.innerHTML = mon.entries.map(en=>
      `<div class="tr-loc">▸ ${en.loc}</div><div><span class="ty">${en.ty}</span> <span class="lv">Lv.${en.lv}</span> <span class="m">${en.m}</span></div>`
    ).join('');
  }
  detailEl.classList.remove('hidden');
});

function openJourney(startIdx, pos){
  journeyStartIdx = startIdx;
  journeyItems = buildJourneyItems(startIdx);
  journeyPos = Math.min(pos, journeyItems.length-1);
  journeyEl.classList.add('show');
  renderJourneyStep();
}

function renderJourneyStep(){
  if(!journeyItems.length) return;
  const item = journeyItems[journeyPos];
  const node = STORY[item.nodeIdx];
  journeyLoc.textContent = node.title;
  journeyFill.style.width = `${((journeyPos+1)/journeyItems.length*100).toFixed(1)}%`;
  journeyCount.textContent = `จุดที่ ${item.nodeIdx+1}/${STORY.length} · ${node.lv || ''}`.trim();
  renderTopRank(node.n);

  let html = '';
  if(item.kind === 'catch'){
    const locs = CATCHMAP[node.n] || [];
    const body = locs.map(L=>`<div class="catchloc"><div class="locname">▸ ${L.loc}</div>${L.mons.map(monRowHTML).join('')}</div>`).join('');
    const hasStar = locs.some(L=>L.mons.some(m=>m.s));
    html = `<div class="journey-kind">📍 จับได้ระหว่างทาง</div><div class="journey-tip" style="border-top:none; padding-top:0; margin-top:2px;">${hasStar?'★ = เตรียมสู้ยิมถัดไป · ตัวเลข = แรงค์':'ตัวเลข = แรงค์ ตามลำดับความคุ้ม'}</div><div style="margin-top:8px;">${body}</div>`;
  } else if(item.kind === 'guide'){
    const g = item.guide;
    const rows = [];
    if(g.loc) rows.push(`<div class="journey-text"><b>📍 ${g.loc}</b></div>`);
    if(g.catch) rows.push(`<div class="journey-text">🎯 <b>แนะนำจับ:</b> ${g.catch}</div>`);
    if(g.legend) rows.push(`<div class="journey-text">✨ <b>โปเกมอนตำนาน:</b> ${g.legend}</div>`);
    html = `<div class="journey-kind">มีอะไรให้ทำที่นี่</div>${rows.join('')}
      ${g.tip?`<div class="journey-tip"><b>คำแนะนำ:</b> ${g.tip}</div>`:''}`;
  } else if(item.kind === 'step'){
    html = `<div class="journey-kind">ภารกิจ</div><div class="journey-text">${item.text}</div>`;
  } else if(item.kind === 'boss'){
    html = `<div class="journey-kind boss">${item.boss.label}</div>
      <div class="journey-mons">${item.boss.mons}</div>
      <div class="journey-tip"><b>วิธีรับมือ:</b> ${item.boss.tip}</div>`;
  } else {
    html = `<div class="journey-kind transition">ต่อไป</div><div class="journey-text">${item.text}</div>`;
  }
  journeyCard.innerHTML = html;
  journeyBack.style.visibility = journeyPos===0 ? 'hidden' : 'visible';

  const isLast = journeyPos === journeyItems.length-1;
  journeyNext.textContent = isLast ? 'จบการเดินทาง 🎉' : 'ทำเสร็จแล้ว ต่อไป →';
  journeyNext.classList.toggle('done', isLast);
  saveJourneyProgress(journeyStartIdx, journeyPos);
}

journeyNext.addEventListener('click', ()=>{
  if(journeyPos < journeyItems.length-1){
    journeyPos++;
    renderJourneyStep();
  } else {
    clearJourneyProgress();
    journeyEl.classList.remove('show');
  }
});
journeyBack.addEventListener('click', ()=>{
  if(journeyPos>0){ journeyPos--; renderJourneyStep(); }
});
document.getElementById('journeyClose').addEventListener('click', ()=>{
  journeyEl.classList.remove('show');
});
document.getElementById('journeyRestart').addEventListener('click', ()=>{
  if(confirm('เริ่มการเดินทางใหม่จากจุดอื่น? ความคืบหน้าปัจจุบันจะถูกล้าง')){
    clearJourneyProgress();
    journeyEl.classList.remove('show');
    openSheet();
  }
});
